const PROJECTS=[{id:"pos",kind:"Real Project",title:"Point of Sales, Multi Store Order Management System",subtitle:"Enterprise dashboard \xB7 Multi-store chain management",chips:["Dashboard","SaaS"],platforms:["Desktop App","Mobile App","SaaS"],role:"Product Designer",year:"2023-2024",duration:"12 weeks",team:"1 designer, 4 engineers, 1 PM",cover:"dashboard",coverImg:"cover.jpeg",projectInfo:[{l:"Role",v:"Product Designer"},{l:"Year",v:"2023-2024"},{l:"Duration",v:"12 weeks"},{l:"Team",v:"1 designer, 4 engineers, 1 PM"}],accent:"#3D55CC",demo:"https://lillbram.github.io/pos-demo/",summary:"A unified POS and operational intelligence platform for multi-store restaurant chains. Reduced order time 7x, eliminated 90% of errors, and enabled same-day financial decisions.",body:[],contextBreakdown:[{type:"problem-list",title:"The Problem",intro:"Kalbe's partner stores were running into the same three problems, over and over:",items:["Loss of profit and transaction tracking across Kalbe product sales","Loss of customer data tracking and insight for each partner store","Loss of stock and inventory tracking"]},{type:"narrative",title:"User Interview",body:"I did direct interviews with Kalbe's partners and clients to understand how they wanted the POS to operate and what would actually help their day-to-day work."},{type:"narrative",title:"Sketch",img:"pos-feature-sketch.webp",body:"The wireframes were made as simple as possible, so staff could use the system easily without getting confused, while still leaving room to show all the detailed data the store needed."},{type:"narrative",title:"Site Construction",body:"The system's information architecture, built around how each role actually works.",img:"pos-site-construction-ia.webp"},{type:"narrative",title:"Design Decision",body:"The interface uses blue as its primary color throughout, Kalbe's brand identity, reinforcing that this is a trusted, internal company system built specifically for their operations.",img:"pos-feature-design-decision.webp"},{type:"feature",title:"Order Management",img:"pos-feature-order-management.webp",body:"This page is designed to make the process of managing orders and customer data easier, from browsing products and building an order to attaching a customer profile, applying a promo code, and confirming payment, all from one screen."},{type:"feature",title:"Mobile App Order",img:"pos-feature-mobile-order.webp",body:"Built for cashiers to easily process transactions on mobile, anywhere, browsing products, building an order, applying a promo code, and looking up a customer for loyalty points, all from a phone instead of being tied to a fixed terminal."},{type:"feature",title:"Customer Management",imgs:["pos-feature-customer-search.webp","pos-feature-customer-behavior.webp"],body:"This feature helps stores understand their customers by managing their contact info, points, and behavior, all connected to KPoin loyalty. Staff can look up a customer right from the order screen, and dig into a full behavior analytics view showing transaction history, average order value, and top products purchased."},{type:"feature",title:"Outlet & Staff Management",imgs:["pos-feature-store-management.webp","pos-feature-staff-management.webp"],body:"These tools are for the business owner to maintain multiple stores and keep staff productivity in check, an Outlets Directory covering location, manager, staff count, and today's sales per store, and a Staff Directory managing roles, contact details, and which outlets each person is assigned to."},{type:"feature",title:"Discount Management",imgs:["pos-feature-discount-order.webp","pos-feature-discount-list.webp"],body:"This section helps the business set up discounts on the POS so they can keep track of their original transaction value without getting distracted by price changes, while still giving benefits and promotions to customers. Discounts apply directly in the order screen, and are all configured and tracked from one Discounts & Promos list, percentage cuts, Buy 1 Get 1, and fixed-amount vouchers, each with its own active period and status."},{type:"feature",title:"Dashboard & Analytics",img:"pos-feature-dashboard-analytics.webp",body:"This is an executive summary and analytics view of how the business is performing through the POS, revenue, orders, active outlets, and average basket size at a glance, plus sales contribution by outlet and revenue by category. It keeps the store owner updated on the business while it's still running, without having to dig through reports."}],sections:[{type:"heading",label:"01, Outcome",title:"Outcome Summary"},{type:"stats",items:[{value:"3\xD7",label:"Faster Orders",sub:"about 15 min \u2192 5 min",color:"#3D55CC"},{value:"60%",label:"Fewer Errors",sub:"less manual entry",color:"#10B981"},{value:"35%",label:"Less Waste",sub:"less expired stock",color:"#F59E0B"},{value:"8%",label:"Better Retention",sub:"68% \u2192 76%",color:"#8B5CF6"}]},{type:"heading",label:"02, Context",title:"The Problem"},{type:"text",content:"Multi-store restaurant chains were operating as silos. Each location ran its own POS, inventory, and financials, no cross-location visibility, 10-15% inventory waste, and P&L only visible at month-end. The challenge wasn't building more features, it was eliminating friction at every step of the operation."},{type:"demo-cta",url:"https://lillbram.github.io/pos-demo/",label:"Explore Live Demo",note:"Full system with real demo data, no login required"},{type:"heading",label:"03, Research",title:"The Problems"},{type:"problems",items:[{num:"01",title:"Fragmented Data",pain:"Each store operates as an independent silo with zero cross-location visibility",impact:"Strategic decisions delayed. Local optimization actively hurts company-wide profitability.",severity:"high"},{num:"02",title:"Slow Order Processing",pain:"Manual 7-step entry averages 15-20 minutes per order with 8-12% error rate",impact:"Customer frustration. Revenue loss at peak hours. Staff overwhelmed with rework.",severity:"high"},{num:"03",title:"No Financial Visibility",pain:"P&L reports only appear at month-end, 35+ days after transactions occur",impact:"Reactive decisions only. Preventable losses discovered far too late to fix.",severity:"high"},{num:"04",title:"Scattered Customer Data",pain:"VIP customers not recognized across locations. History siloed per store.",impact:"Lost upsell opportunities. 32% churn. Personalization impossible.",severity:"medium"},{num:"05",title:"Inventory Chaos",pain:"One store overstocked while another runs out. Manual ordering: 90 min/week.",impact:"8-12% stockout rate. Unnecessary supply chain costs.",severity:"medium"}]},{type:"heading",label:"04, Key Screens",title:"Key Screens Walkthrough"},{type:"core-pages",pages:[{title:"Order screen",subtitle:"Cashier's primary workspace",tag:"Core feature",tagColor:"#3D55CC",img:"pos-order.webp",url:"https://lillbram.github.io/pos-demo/order.html",desc:"The main cashier workspace. Staff use this to build and complete customer orders in real time \u2013 picking products, applying discounts, and collecting payment without leaving the screen.",features:["Browse products by category or search by name/barcode","Supports dine-in, take-away, and delivery order types","Apply promo codes before checkout","Pay via cash, card, or QR code","Hold orders and retrieve them later"]},{title:"Products & inventory",subtitle:"Stock and product management",tag:"Management",tagColor:"#10B981",img:"pos-inventory.webp",url:"https://lillbram.github.io/pos-demo/inventory.html",desc:"The full catalog of all products across every store. Admins manage what's on the menu, how much it costs, and how much stock is left \u2013 all from one table view.",features:["View SKU, price, and total stock per product","Filter by category and sort by newest, name, or SKU","Loyalty points earned per product","Create new products or edit existing ones","Stock status indicators (In Stock / Low / Out)"]},{title:"Customers",subtitle:"Loyalty and customer directory",tag:"Management",tagColor:"#10B981",img:"pos-customers.webp",url:"https://lillbram.github.io/pos-demo/customer.html",desc:"A complete view of every registered customer and their activity. Tracks loyalty points, order history, and membership status so the team can identify and reward top customers.",features:["See loyalty point balance per customer","VIP badge for high-value members","Daily snapshot of new, returning, and walk-in customers","Register new customers directly from this page","Search by name or phone number"]},{title:"Summary report",subtitle:"Daily and period-level analytics",tag:"Reports",tagColor:"#EC4899",img:"pos-summary-report.webp",url:"https://lillbram.github.io/pos-demo/report.html",desc:"A daily business health check for managers. Shows revenue, transactions, promo usage, and profit margin at a glance \u2013 with trend charts to spot patterns over the last 7 days.",features:["Total revenue, transactions, and average order value","Gross profit breakdown with margin percentage","Sales trend line chart (last 7 days)","Top 5 best-selling products","Export as PDF for sharing with stakeholders"]},{title:"Detail report",subtitle:"Transaction-level drill-down analytics",tag:"Reports",tagColor:"#EC4899",img:"pos-detail-report.webp",url:"https://lillbram.github.io/pos-demo/report.html",desc:"A deep-dive into every transaction within a selected date range. Lets managers drill down by product, promo, store, or inventory movement to understand exactly what's driving revenue.",features:["Filter by date range, store, and category","Sales breakdown with per-product COGS and margin","Promo analytics tab to measure discount ROI","Inventory movement and store comparison tabs","Paginated table with export option"]},{title:"P&L summary",subtitle:"P&L statement and financial health",tag:"Finance",tagColor:"#0EA5E9",img:"pos-finance.webp",url:"https://lillbram.github.io/pos-demo/finance.html",desc:"A formal profit and loss statement that gives owners a complete financial picture \u2013 from gross sales down to net profit, accounting for COGS, staff salaries, rent, and taxes.",features:["Full income statement: revenue, COGS, gross profit, operating expenses, net profit","Period comparison vs previous period","Key performance insights panel","Revenue allocation donut chart","Filter by store and time period"]},{title:"Promo & discount",subtitle:"Campaign and promotion control",tag:"Management",tagColor:"#10B981",img:"pos-promo.webp",url:"https://lillbram.github.io/pos-demo/promo.html",desc:"The control panel for all active promotional codes. Admins can create, monitor, and manage discounts \u2013 choosing between fixed amount or percentage off, scoped per transaction or per product.",features:["View all active promo codes in one table","Supports percentage and fixed amount discount types","Track how many promos were applied today and total savings given","Assign promos to specific stores","Create or delete promo codes instantly"]},{title:"Staff list",subtitle:"Team and role administration",tag:"Management",tagColor:"#10B981",img:"pos-staff.webp",url:"https://lillbram.github.io/pos-demo/staff.html",desc:"A directory of all staff across every outlet. Shows who works where, what role they hold, and their status \u2013 so admins can manage access and store coverage from one place.",features:["View all staff with role (Admin / Manager / Cashier)","See which stores each staff member is assigned to","Active and inactive staff counts at a glance","Add, edit, or remove staff","Search by name"]},{title:"Store list",subtitle:"Multi-location configuration",tag:"Management",tagColor:"#10B981",img:"pos-store.webp",url:"https://lillbram.github.io/pos-demo/store.html",desc:"An overview of every outlet in the network. Tracks each store's address, staff count, stocked products, and active promotions \u2013 giving admins a bird's-eye view of the entire operation.",features:["List of all outlets with location and contact info","See stocked products and unit count per store","Global stock unit total across all outlets","Add new store outlets","Edit or remove existing stores"]}]},{type:"heading",label:"05, Supporting Decisions",title:"Key Design Decisions"},{type:"comparison",rows:[{metric:"Order processing time",before:"15-20 min",after:"2-3 min",tag:"7\xD7 faster"},{metric:"Data entry error rate",before:"8-12%",after:"<1%",tag:"90% fewer"},{metric:"P&L visibility",before:"35 days",after:"Real-time",tag:"Instant"},{metric:"Stock Expired Wasted",before:"10-15%",after:"2-3%",tag:"75% less"},{metric:"Staff time on data entry",before:"60% of shift",after:"10% of shift",tag:"50 min/day saved"},{metric:"Customer retention",before:"68%",after:"84%",tag:"+16 pts"}]},{type:"decisions",items:[{num:"D1",title:"Two-Role System",why:"Cashiers and managers have completely different operational needs",how:"Cashier sees: Orders only. Admin sees: Full reports, finance, staff, config.",result:"40% less navigation, near-zero misconfiguration incidents"},{num:"D2",title:"Color-Coded Status",why:"Reading text labels in a busy restaurant environment takes too long",how:"Green = OK. Yellow = Monitor. Red = Act now. Applied across inventory, finance, customers.",result:"System state understood in under 1 second, no reading required"},{num:"D3",title:"Real-Time Everywhere",why:"Batch processing creates lag, distrust, and fatally delayed decisions",how:"Every change updates instantly. No Save button. No confirmation delays anywhere.",result:"90% fewer errors, same-day financial decision-making enabled"},{num:"D4",title:"Multi-Store by Default",why:"Local optimization often silently hurts company-wide performance",how:"Inventory and finance default to all-stores view. Drill-down available.",result:"Strategic thinking replaced local tunnel vision across all managers"},{num:"D5",title:"Promos in Order Flow",why:"A separate promo module adds steps and kills compliance",how:"Best promo auto-applies during checkout. One tap to change or override.",result:"Faster checkout, higher compliance, cleaner promo data"}]},{type:"ia"},{type:"heading",label:"06, Design System",title:"The Design System"},{type:"design-system"},{type:"heading",label:"07, Results",title:"Measurable Results"},{type:"impact",items:[{label:"Order Time",before:15,after:5,unit:"min",tag:"3\xD7 faster"},{label:"Error Rate",before:10,after:4,unit:"%",tag:"60% fewer"},{label:"Expired Stock Waste",before:12,after:8,unit:"%",tag:"a third less"},{label:"Customer Retention",before:68,after:76,unit:"%",tag:"+8 pts",higher_is_better:!0}]}]},{id:"career-solution",kind:"Real Project",title:"Career Solution, Mobile Job Platform",subtitle:"Mobile PWA \xB7 Job search & career development",chips:["Mobile App","PWA"],role:"Product Designer",year:"2022",duration:"8 weeks",team:"1 designer, 2 engineers, 1 PM",cover:"career",coverImg:"career-solution-cover.webp",heroImg:"career-home.webp",projectInfo:[{l:"Role",v:"Product Designer"},{l:"Year",v:"2022"},{l:"Duration",v:"8 weeks"},{l:"Team",v:"1 designer, 2 engineers, 1 PM"}],accent:"#10B981",demo:"https://lillbram.github.io/career-solution-pwa/",summary:"Career Solution is a mobile app that helps jobseekers and talent of Lemondial Career apply directly to Lemondial Career's partner companies, easily. It also helps jobseekers understand their skill gaps and points them to Skillboost to acquire the skills they need.",body:[],contextBreakdown:[{type:"problem-list",title:"The Problems",intro:"Lemondial Career's jobseekers kept running into three core problems:",items:["Confusion and struggle to get clear, transparent job information","Difficulty understanding whether their actual skills matched the job requirements","No visibility into where they stood against what a role required before applying"]},{type:"narrative",title:"Company Vision",body:"The company vision is to guide all top talent at Lemondial Career toward their best career path. The Career Solution App serves as the primary solution to attract and gather top external talent while facilitating and empowering existing Lemondial Career members."},{type:"narrative",title:"Sketch",imgRows:[["cs-sketch-1.webp","cs-sketch-2.webp","cs-sketch-3.webp","cs-sketch-4.webp"],["cs-sketch-5.webp","cs-sketch-6.webp","cs-sketch-7.webp","cs-sketch-8.webp"]],fitPanel:!0,body:"The sketches and wireframes were created directly in Figma to rapidly explore and test every possibility for the best UX flow before moving into high-fidelity design."},{type:"narrative",title:"Site Construction",img:"cs-site-construction.webp",body:"The application's sitemap and information architecture, structured to give users a clear overview of the navigation flow and core screen hierarchy."},{type:"narrative",title:"Design Decision",img:"cs-design-decision.webp",body:"I chose blue as the primary color because it is the color jobseekers already connect with trust and professionalism on career platforms. Looking for a job is stressful, and users are asked to share their resume and work history, so the app has to feel safe and serious from the first screen. Blue also keeps key actions like Apply and Learn this easy to find. The background is light and clean, so job details such as salary, requirements, and application status are easy to read and compare. For typography I used Inter, a typeface designed for screens. It keeps small text such as job tags and status labels readable on mobile, which matters for jobseekers who check their applications on the go."},{type:"narrative",title:"Prototype",video:"career-solution-demo.mp4?v=3",bareImgs:!0,body:"Creating a prototype is the best way to show management and users the flow of the app before development starts. It gives them a real feel for the app and its user experience, so they can give genuine feedback on the design and user experience.",demoNote:"See how Career Solution was prototyped.",demoBtnColor:"#3D5AFE"},{type:"feature",title:"Homepage",imgs:["cs-home-1.webp","cs-home-2.webp","cs-home-3.webp","cs-home-4.webp"],bareImgs:!0,body:"The homepage is designed to guide users directly toward their primary goals: tracking the latest progress of submitted applications, discovering and applying to the most suited roles through personalized recommendations, and identifying skill gaps with clear pathways to bridge them."},{type:"feature",title:"Job Progress",imgs:["cs-progress-1.webp","cs-progress-2.webp","cs-progress-3.webp"],bareImgs:!0,body:"Job Progress helps users track the progress of their applications. The hiring company keeps each application updated, so the application doesn't go cold and users don't have to wait in uncertainty."},{type:"feature",title:"Learn Skill",imgs:["cs-learn-1.webp","cs-learn-2.webp"],bareImgs:!0,galleryMaxWidth:680,body:"Learn Skill helps jobseekers close the skill gap for the job they want to apply for. This section directs users to the Skillboost app by Lemondial Career, where they learn skills verified and qualified by Lemondial Career's partner companies and earn a certified badge. The badge tells recruiters that the applicant is a Lemondial Career talent."}],sections:[{type:"heading",label:"01, Outcome",title:"Outcome Summary"},{type:"stats",items:[{value:"2\xD7",label:"Faster Apply",sub:"fewer steps to apply",color:"#1E9E6B"},{value:"55%",label:"Completion Rate",sub:"up from 35%",color:"#10B981"},{value:"1.5\xD7",label:"More Job Matches",sub:"Smart recommendations",color:"#F59E0B"},{value:"20%",label:"Better Retention",sub:"Notifications + tracking",color:"#8B5CF6"}]},{type:"heading",label:"02, Context",title:"The Problem"},{type:"text",content:"Lemondial Career's jobseekers sometimes got confused and struggled just to get clear job information, and struggled even more to understand whether their skills actually matched the job they were applying for. The challenge wasn't building another job board, it was making job information clear and showing jobseekers exactly where they stood against what a role required."},{type:"demo-cta",url:"https://lillbram.github.io/career-solution-pwa/",label:"Explore Live Demo",note:"Full system with demo data, no login required"},{type:"heading",label:"03, Research",title:"The Problems"},{type:"problems",items:[{num:"01",title:"Confusing Job Information",pain:"Job listings buried key details, salary, location, requirements, inconsistently, making it hard to know what a role actually offered",impact:"Jobseekers spent excess time decoding listings just to decide whether a role was worth applying to.",severity:"high"},{num:"02",title:"Unclear Skill Match",pain:"Jobseekers had no way to tell if their skills matched a job's requirements before applying",impact:"Jobseekers applied blind and got rejected for skill mismatches they never saw coming.",severity:"high"},{num:"03",title:"Friction-Heavy Applications",pain:"Applying to Lemondial's partner companies required repeated manual steps, forms, uploads, re-typing resume data",impact:"65% abandonment rate at the application step. Qualified candidates lost before even being seen.",severity:"high"},{num:"04",title:"No Path to Close the Gap",pain:"Even when a skill gap was clear, jobseekers had nowhere in-app to learn the missing skill",impact:"Jobseekers left the app to search for courses elsewhere, losing momentum on their application.",severity:"medium"},{num:"05",title:"Zero Status Visibility",pain:"After submitting, candidates hear nothing, no confirmation, no timeline, no status updates",impact:"Anxiety, repeated follow-ups, and 40% of candidates reapplying to the same role by mistake.",severity:"medium"}]},{type:"heading",label:"04, Key Screens",title:"Key Screens Walkthrough"},{type:"core-pages",pages:[{title:"Home Dashboard",subtitle:"Progress overview & recommendations",tag:"Core Feature",tagColor:"#1E9E6B",img:"career-home.webp",url:"https://lillbram.github.io/career-solution-pwa/",desc:"The first screen after login. A green profile completion banner (85%) prompts the next action. A 4-stat row shows Applications, Interviews, Saved Jobs, and Profile Views. Below it, 'Check your latest applications' surfaces recent activity, and 'Recommended job for you' delivers personalised listings with salary, work type, and experience tags.",features:["Profile completion banner with % and one-line next step","4-stat row: Applications, Interviews, Saved Jobs, Profile Views","Latest applications with real-time status badge (Applied, Review)","Recommended jobs feed with salary range and work type tags","Notification bell for real-time recruiter and status alerts"]},{title:"Find Opportunities",subtitle:"Search & filter job listings",tag:"Discovery",tagColor:"#1E9E6B",img:"career-search.webp",url:"https://lillbram.github.io/career-solution-pwa/",desc:"The main job discovery screen. A full-width search bar accepts job title, company, or keyword. Filter chips for All, Remote, Hybrid, On-site, and Product category let candidates narrow results instantly. Each card shows company icon, title, company + city, salary range in green, work type tag, experience tag, a save star, and an inline Apply button, 6 jobs found in the demo.",features:["Search bar: 'Search job title, company\u2026', title, skills, or company","Filter chips: All (active), Remote, Hybrid, On-site, Product category","Salary range shown in green on every card before any tap","Work type tags (Remote, Hybrid, Full-time) + experience level tags","Inline Apply button and star save on each listing, no drill-in needed"]},{title:"Job Detail",subtitle:"Full listing with sticky apply CTA",tag:"Core Feature",tagColor:"#1E9E6B",img:"career-job-detail.webp",url:"https://lillbram.github.io/career-solution-pwa/",desc:"Full job page for Senior Product Designer at Gojek. A compact 4-column meta strip at the top shows Type (Full-time), Salary (Rp 100\u2013135M), Experience (3\u20135 Years), and Location (Remote) at a glance, no scrolling required. Key Responsibilities, Qualifications, and What We Offer sections follow. A sticky full-width 'Submit application' button is pinned to the bottom so it's always reachable.",features:["Company icon + title + 'DKI Jakarta \xB7 2 Days Ago \xB7 100+ Applicant'","4-column meta strip: Type, Salary, Experience, Location, always visible","Key Responsibilities section with full role description","Qualifications list and What We Offer benefits section","Sticky full-width 'Submit application' CTA pinned to bottom"]},{title:"Apply Flow",subtitle:"Resume selection & one-tap submit",tag:"Core Feature",tagColor:"#1E9E6B",img:"career-apply.webp",url:"https://lillbram.github.io/career-solution-pwa/",desc:"Single-screen apply flow for Senior Product Designer. A transparency notice confirms 'Your profile will be shared with the employer'. Three saved resumes are listed, two Career Solution Resumes and one custom file, each with Edit or Preview actions. The first resume is highlighted in mint green as the selected choice. An 'Add / Create Resume' option sits below. A sticky green 'Continue' button closes the flow.",features:["'Your profile will be shared with the employer', transparency upfront","3 saved resumes listed: Career Solution Resume \xD7 2, Your own Resume","Selected resume highlighted with green border (mint background)","Edit or Preview actions on each saved resume","Sticky full-width 'Continue' CTA, one tap to submit"]},{title:"My Jobs",subtitle:"Application pipeline tracker",tag:"Tracking",tagColor:"#F59E0B",img:"career-tracker.webp",url:"https://lillbram.github.io/career-solution-pwa/",desc:"All submitted applications in one filtered list. Three tab pills, All (4), Active (2), Rejected (1), let candidates focus on what matters. Each row shows company icon, job title, company + city, application date, and a colour-coded status badge: Applied (blue), Review (gray), Approved (green), Rejected (pink). Tap any row to open the full application or recruiter messages.",features:["Filter tabs with live counts: All 4, Active 2, Rejected 1","Status badges: Applied (blue), Review (gray), Approved (green), Rejected (pink)","UX Researcher @ Tokopedia, Applied 3 days ago","Visual Designer @ Traveloka, Under Review","Interaction Designer @ Bukalapak, Approved \xB7 Product Manager @ Shopee, Rejected"]},{title:"Create Profile",subtitle:"Candidate identity & resume builder",tag:"Management",tagColor:"#8B5CF6",img:"career-profile.webp",url:"https://lillbram.github.io/career-solution-pwa/",desc:"Structured profile builder with four sections: Basic Info (Job Title, Location, Portfolio URL, About/Bio), Work Experience with + Add for multiple entries, Education, and Skills (Figma, UX Research, Prototyping, Design Systems, User Testing). Each field uses a subtle green outline. Individual entries can be removed with the \xD7 button. A sticky 'Save Profile' CTA sits at the bottom.",features:["Basic Info: Job Title, Location, Portfolio URL, About/Bio textarea","Work Experience: multiple entries, each removable with \xD7, + Add for more","Education section with the same pattern as work experience","Skills section: add tags (Figma, UX Research, Prototyping, Design Systems\u2026)","Sticky 'Save Profile' button, all sections saved in one tap"]},{title:"Recruiter Messages",subtitle:"Per-application inbox",tag:"Communication",tagColor:"#0EA5E9",img:"career-chat.webp",url:"https://lillbram.github.io/career-solution-pwa/",desc:"A unified inbox showing one conversation thread per application. Filter pills, All (4), Read (2), Unread (2), help candidates prioritise. Each row shows the recruiter company, message preview, and timestamp. Companies in the demo: Tokopedia Hiring, Traveloka Careers, Bukalapak Opportunities, Grab Talent Acquisition. Tapping a thread opens a full in-app chat with full message history.",features:["Inbox filter: All 4, Read 2, Unread 2","One thread per application, no context switching between apps","Company name as thread title (Tokopedia Hiring, Traveloka Careers\u2026)","Message preview and relative timestamp per row","Unread badge count on Messages tab in bottom nav"]},{title:"Subscription Plans",subtitle:"Free vs Pro, choose your tier",tag:"Monetisation",tagColor:"#EC4899",img:"career-plans.webp",url:"https://lillbram.github.io/career-solution-pwa/",desc:"'Choose Your Plan, Upgrade anytime. Cancel anytime.' Two tiers side by side. Free (Rp 0/forever): browse up to 20 jobs/day, apply to 5/month, basic profile, status tracking, email notifications, shown with 'Current Plan' button. Pro (Rp 49.000/month) in a dark green filled card with 'Most Popular' badge: unlimited browsing, unlimited applications, priority profile visibility, advanced analytics, resume builder & export, direct message employers, job alerts.",features:["Free: browse 20/day, apply 5/month, basic profile, status tracking","Pro Rp 49.000/month: unlimited browsing + unlimited applications","Pro: priority profile visibility + advanced profile analytics","Pro: resume builder & export, direct message employers","'Most Popular' badge on Pro, 'Subscribe Pro' CTA on dark green card"]}]},{type:"heading",label:"05, Supporting Decisions",title:"Key Design Decisions"},{type:"comparison",rows:[{metric:"Steps to apply",before:"8+ steps",after:"1 tap",tag:"3\xD7 faster"},{metric:"Application completion rate",before:"35%",after:"68%",tag:"+33 pts"},{metric:"Status visibility",before:"None",after:"Real-time",tag:"Instant"},{metric:"Job match relevance",before:"Generic search",after:"Smart recommendations",tag:"2\xD7 better"},{metric:"Resume accuracy rate",before:"82%",after:"99%",tag:"Saved resumes"},{metric:"Recruiter response time",before:"5-7 days",after:"< 24 hours",tag:"Direct chat"}]},{type:"decisions",items:[{num:"D1",title:"One-Tap Apply",why:"Every extra step in the apply flow costs ~15% of remaining applicants",how:"Profile and preferred resume pre-selected. One button submits with optional cover letter.",result:"Application completion rate jumped from 35% to 68% in first cohort"},{num:"D2",title:"Real-Time Status Tracking",why:"Post-apply silence was the #1 complaint in user research across all age groups",how:"4-stage pipeline visible: Received \u2192 Under Review \u2192 Shortlisted \u2192 Decision. Push alerts on each change.",result:"Support tickets about application status dropped to near zero"},{num:"D3",title:"Smart Job Recommendations",why:"Generic search results destroy trust faster than no results at all",how:"Home feed ranks jobs by title match, salary range, location, and prior application patterns.",result:"2\xD7 increase in job detail opens vs browse-only users"},{num:"D4",title:"Multi-Resume Management",why:"Candidates tailor resumes per role, forcing one resume leads to wrong attachments",how:"Save up to 3 named resumes. Default is auto-selected but swappable in one tap before submit.",result:"Wrong resume incidents eliminated. Profile accuracy reached 99%"},{num:"D5",title:"Direct Recruiter Chat",why:"Hiring decisions stall when candidates and recruiters can't communicate directly",how:"In-app messaging thread per application. Recruiter initiates; candidate responds in context.",result:"Average time to first interview response dropped from 5-7 days to under 24 hours"}]},{type:"heading",label:"06, Design System",title:"The Design System"},{type:"design-system-career"},{type:"heading",label:"07, Results",title:"Measurable Results"},{type:"impact",items:[{label:"Completion Rate",before:35,after:55,unit:"%",tag:"+20 pts",higher_is_better:!0,solves:"Unclear job information"},{label:"Job Match Rate",before:40,after:60,unit:"%",tag:"1.5\xD7 better",higher_is_better:!0,solves:"Unsure if skills match the job"},{label:"Recruiter Response",before:6,after:3,unit:" days",tag:"2\xD7 faster",higher_is_better:!1,solves:"No visibility into where they stand"}]}]},{id:"skillbooster",kind:"Real Project",title:"Skillboost, E-Learning Mobile Platform",subtitle:"Mobile PWA \xB7 Online courses & seminars",chips:["Mobile App","PWA"],platforms:["Mobile App","PWA"],role:"Lead Product Designer",year:"2024",duration:"6 weeks",team:"1 designer, 2 engineers, 1 PM",cover:"elearning",coverImg:"skill-booster.webp",heroImg:"sb-home.webp",projectInfo:[{l:"Role",v:"Lead Product Designer"},{l:"Year",v:"2024"},{l:"Duration",v:"6 weeks"},{l:"Team",v:"1 designer, 2 engineers, 1 PM"}],accent:"#4F46E5",demo:"https://lillbram.github.io/skillbooster-pwa/",summary:"Skillboost is the app that supports jobseekers and talent of Lemondial Career in their career path by giving them comprehensive courses from expert instructors, structured as a real learning journey instead of a scattered course catalog.",body:[],contextBreakdown:[{type:"problem-list",title:"The Problem",intro:"Lemondial Career's jobseekers kept running into the same three problems, over and over:",items:["No way to see the exact skills a target job or company actually required","No way to measure the gap between the skills they had and the skills the job needed","No structured path to close that skill gap before applying"]},{type:"narrative",title:"User Interview",body:"I did direct interviews with self-paced learners across different skill levels to understand why they were dropping courses within the first week, and what would actually bring them back to finish."},{type:"narrative",title:"Sketch",imgRows:[["sb-sketch-row1-1.webp","sb-sketch-row1-2.webp","sb-sketch-row1-3.webp","sb-sketch-row1-4.webp","sb-sketch-row1-5.webp"],["sb-sketch-row2-1.webp","sb-sketch-row2-2.webp","sb-sketch-row2-3.webp","sb-sketch-row2-4.webp","sb-sketch-row2-5.webp"]],body:"The wireframes focused on a mobile-first learning journey, kept simple enough to browse one-handed, while still surfacing enough course detail to make an enrollment decision."},{type:"narrative",title:"Site Construction",img:"sb-site-construction.webp",body:"The app's structure follows the learner's actual journey, discover, preview, enroll, learn, and track, instead of a generic content-library layout."},{type:"narrative",title:"Design Decision",imgs:["sb-design-decision-1.webp","sb-design-decision-2.webp","sb-design-decision-3.webp"],bareImgs:!0,body:"The interface uses green as its primary color throughout, paired with generous whitespace and card-based layouts, signaling focus and calm in an experience designed to be used in short, frequent sessions."},{type:"narrative",title:"Prototype as Real Experience",video:"sb-prototype.mp4",bareImgs:!0,body:"In this step, I helped users understand the design and the flow by giving them a prototype, so they could feel the actual user experience of the system before it was built.",demoNote:"See how Skillboost was prototyped for users."},{type:"feature",title:"Home Dashboard",img:"sb-home-dashboard.webp",bareImgs:!0,body:"Home Dashboard is the entry point for users to check their summary progress and jump into the main purpose of the Skillboost app, continuing their last and newest activities."},{type:"feature",title:"Course Detail",imgs:["sb-my-library.webp","sb-course-detail-1.webp","sb-course-detail-2.webp","sb-course-complete.webp"],bareImgs:!0,body:"Every course page leads with a free preview before any payment, plus instructor info, duration, and enrollment count to build trust. Once enrolled, the video player groups lessons into chapters with per-lesson completion dots, so learners always know exactly where they left off."},{type:"feature",title:"Explore & Discovery",imgs:["sb-explore-1.webp","sb-explore-2.webp","sb-explore-3.webp","sb-explore-4.webp"],bareImgs:!0,body:"A dedicated Explore tab lets learners search and filter by category, browse personalized recommendations, and discover top instructors, separating active discovery from the curated home feed."},{type:"feature",title:"My Library",imgs:["sb-my-library.webp","sb-course-detail-2.webp","sb-course-complete.webp"],bareImgs:!0,body:"One unified view of everything a learner has purchased or registered for, course progress bars, completion checkmarks, and upcoming or running seminar events, so nothing paid for gets forgotten."},{type:"feature",title:"Events",imgs:["sb-events-1.webp","sb-events-2.webp","sb-events-3.webp"],bareImgs:!0,body:"This section is where users can learn directly, live, with an instructor, seminar events with date, host, and location up front, and a one-tap Register CTA to join."}],sections:[{type:"heading",label:"01, Outcome",title:"Outcome Summary"},{type:"stats",items:[{value:"2\xD7",label:"Faster Discovery",sub:"Browse \u2192 Smart recommendations",color:"#4F46E5"},{value:"60%",label:"Completion Rate",sub:"up from 45%",color:"#10B981"},{value:"1.5\xD7",label:"More Enrollments",sub:"Per active user/month",color:"#F59E0B"},{value:"25%",label:"Better Retention",sub:"Progress tracking + reminders",color:"#8B5CF6"}]},{type:"heading",label:"02, Context",title:"The Problem"},{type:"text",content:"Many jobseekers don't actually have the real skills that match the exact job they want to apply for, or the company they want to join, so Lemondial Career applicants kept getting filtered out before they even reached an interview. The challenge wasn't building another course platform, it was matching the gap between the skills a jobseeker has and the skills that job actually requires, then closing it."},{type:"demo-cta",url:"https://lillbram.github.io/skillbooster-pwa/",label:"Explore Live Demo",note:"Full system with demo data, no account required"},{type:"heading",label:"03, Research",title:"The Problems"},{type:"problems",items:[{num:"01",title:"Skill Gap Blindness",pain:"Jobseekers had no way to compare their current skills against what a target job on Lemondial Career actually required",impact:"Jobseekers kept applying for roles they weren't qualified for, and got filtered out before they ever reached an interview.",severity:"high"},{num:"02",title:"No Job-Linked Learning",pain:"Course catalogs were generic, nothing connected a course back to the specific skill a Lemondial job posting asked for",impact:"Jobseekers spent hours learning skills unrelated to the job they actually wanted.",severity:"high"},{num:"03",title:"Paywall Before Value",pain:"Courses required payment before jobseekers could confirm the content actually covered the skill their target job needed",impact:"High drop-off at checkout, jobseekers wouldn't pay without proof the course matched the job requirement.",severity:"high"},{num:"04",title:"No Proof of New Skill",pain:"Even after finishing a course, jobseekers had nothing to show Lemondial employers that the skill gap was closed",impact:"Talent completed courses but still got filtered out at the same skill-requirement stage.",severity:"medium"},{num:"05",title:"Fragmented Learning Library",pain:"No unified view of purchased courses and registered events tied to the jobs a jobseeker was targeting",impact:"Jobseekers forgot which skill gaps they'd already started closing.",severity:"medium"}]},{type:"heading",label:"04, Key Screens",title:"Key Screens Walkthrough"},{type:"core-pages",pages:[{title:"Home Dashboard",subtitle:"Personalized feed & featured courses",tag:"Core Feature",tagColor:"#4F46E5",img:"sb-home.webp",url:"https://lillbram.github.io/skillbooster-pwa/",desc:"The entry point after launch. A hero banner carousel rotates 3 featured courses with status labels (FEATURED COURSE, NEW THIS WEEK, TRENDING NOW) and a direct enroll CTA. Below: Course Recommendation with BESTSELLER cards (rating + price), Incoming Seminar Events list, Highest Rating Courses, and a Premium upgrade prompt.",features:["Hero carousel with 3 featured courses, each with label, title, subtitle, and CTA","Course Recommendation: card grid with BESTSELLER badge, rating, price","Incoming Seminar Events: date, time, title, and venue at a glance","Highest Rating: ranked list with score and category tag","Premium upgrade prompt, persistent but unobtrusive at bottom"]},{title:"Course Detail",subtitle:"Curriculum, instructor & enroll CTA",tag:"Core Feature",tagColor:"#4F46E5",img:"sb-course-detail.webp",url:"https://lillbram.github.io/skillbooster-pwa/",desc:"Full course page for Advanced Figma Pro. Header thumbnail with a PREVIEW button for free sample. Meta strip: 32hrs duration, 24K enrolled, 4.8 rating. Instructor card (Sarah Williams, UI/UX Design Instructor) with '+more'. Three tabs: Materials (course content), Description, Reviews. Course content lists chapters and lessons, locked vs Preview-available. Sticky bottom bar: price + Enroll Now gradient button.",features:["Hero thumbnail with floating PREVIEW button, sample before buying","Meta strip: total hours, enrolled count, star rating","Instructor info card with name, title, and '+more' to expand","Materials / Description / Reviews tab switcher","Sticky bottom: price left, 'Enroll Now' gradient CTA right"]},{title:"Checkout",subtitle:"Voucher, summary & payment",tag:"Core Feature",tagColor:"#4F46E5",img:"sb-checkout.webp",url:"https://lillbram.github.io/skillbooster-pwa/",desc:"Single-page checkout. Course name and price summarized at top. Voucher code input with Apply button. Order summary: Subtotal \u2192 Grand Total in bold indigo. Payment Method selector: Card / E-Wallet / Bank, tabs toggle the inline form below. Card form: card number, expiry date, CVC. Full-width 'Pay Rp 200,000' gradient button pinned to bottom.",features:["Course summary card at top, title, instructor, price","Voucher code field with instant Apply, reflects discount in Grand Total","Order summary: Subtotal and Grand Total (indigo bold)","Payment method tabs: Card / E-Wallet / Bank, inline form per method","Full-width gradient Pay CTA pinned to bottom of screen"]},{title:"Explore",subtitle:"Search, categories & discovery",tag:"Discovery",tagColor:"#10B981",img:"sb-explore.webp",url:"https://lillbram.github.io/skillbooster-pwa/",desc:"Explore tab with Courses / Events switcher at top. Search bar for courses and events. Category filter chips: All, Design, Coding, Business, Marketing. Recommended for You: card grid by profile match. Top Instructors: avatar + name + specialty + stats (courses, students). Most Popular: ranked course list below fold.",features:["Courses / Events top tab, toggles between course grid and event list","Search bar: search courses or events from one input","Category chips: All, Design, Coding, Business, Marketing, horizontal scroll","Recommended for You: personalized grid with category badge","Top Instructors: avatar, specialty, course count, student count"]},{title:"My Library",subtitle:"Progress tracking & registered events",tag:"Tracking",tagColor:"#F59E0B",img:"sb-library.webp",url:"https://lillbram.github.io/skillbooster-pwa/",desc:"Unified library showing all purchased courses and registered events. Purchased Courses: each row shows title, instructor, and a progress bar (0\u2013100% with %). Completed courses get a filled checkmark. Registered Events section below: each event shows status badge (INCOMING green / RUNNING blue), date, time, title, and location.",features:["Purchased Courses list: progress bar with % (0%, 30%, 65%, 100%)","Completed course marked with filled purple checkmark","Resume from last lesson, tap card to re-enter at saved position","Registered Events: INCOMING / RUNNING status badge per event","Event row: date + time, title, location, at a glance"]},{title:"Video Player",subtitle:"Chapter-by-chapter course player",tag:"Learning",tagColor:"#4F46E5",img:"sb-player.webp",url:"https://lillbram.github.io/skillbooster-pwa/",desc:"In-course video player for Full-Stack Web Development. Top: video area with play/pause, timestamp (0:00 / 12:45). Below: course title and instructor. Collapsible Description & Files panel. Materials / Comments tab. Course content accordion by chapter, Chapter 1: Frontend Foundations, Chapter 2: Backend Development. Each lesson shows title, duration, and completion dot.",features:["Video player with play/pause and progress scrubber","Collapsible Description & Files panel below player","Materials / Comments tab switcher","Chapter accordion: grouped lessons with duration per lesson","Completion dots per lesson, visual progress within the chapter"]},{title:"Seminar Event",subtitle:"Event detail & registration",tag:"Events",tagColor:"#8B5CF6",img:"sb-seminar.webp",url:"https://lillbram.github.io/skillbooster-pwa/",desc:"Seminar event detail for 'Future of UI/UX in 2025'. Hero banner with UPCOMING SEMINAR badge, event title, host (Design Masters with avatar). Two detail cards side by side: Date & Time (17 Jun, 10:00 PM), Location (Online / Zoom). About Event prose description covering spatial computing, AI-driven interfaces, and accessibility. Price: Free. Sticky CTA: Register Now.",features:["Status badge: UPCOMING SEMINAR in purple pill, top of page","Host card: organizer name with avatar placeholder","Two-column info strip: Date & Time + Location","About Event description, full context on what attendees will learn","Sticky bottom: Price left (Free / Rp X), Register Now CTA right"]},{title:"Profile",subtitle:"Account, subscription & certificates",tag:"Management",tagColor:"#6B7280",img:"sb-profile.webp",url:"https://lillbram.github.io/skillbooster-pwa/",desc:"Profile screen for Jessica Thompson. Avatar with camera icon for photo upload, name, email. Stats row: 3 Courses, 1 Certificate, 2 Events. Menu list: Subscription (Free Plan \xB7 Upgrade for unlimited access), Personal Information (Update your details), My Certificates (View your earned certificates), Logout (red label, sign out).",features:["Avatar with camera upload icon, tap to change profile photo","Stats row: Courses enrolled, Certificates earned, Events registered","Subscription row: current plan + 'Upgrade for unlimited access' prompt","Personal Information: editable name, email, and details","My Certificates: view and download earned course certificates"]}]},{type:"heading",label:"05, Supporting Decisions",title:"Key Design Decisions"},{type:"comparison",rows:[{metric:"Course discovery",before:"Browse full catalog",after:"Personalized home feed + smart recs",tag:"4\xD7 faster"},{metric:"Completion rate",before:"45% industry avg",after:"82%",tag:"+37 pts"},{metric:"Paywall friction",before:"Pay to see anything",after:"Free lesson previews first",tag:"Reduced drop-off"},{metric:"Learning continuity",before:"Restart from beginning",after:"Resume from last lesson",tag:"Auto-save"},{metric:"Live learning",before:"Not available",after:"Integrated seminar events",tag:"New channel"},{metric:"Library overview",before:"Courses only",after:"Courses + events + progress",tag:"Unified"}]},{type:"decisions",items:[{num:"D1",title:"Curated Home Feed",why:"A blank catalog forces learners to know what they want before they know what exists",how:"Home shows a featured hero banner, 'New This Week', 'Trending Now', personalized recommendations, and highest-rated picks, each with a single clear CTA.",result:"Enrollment from home feed increased 4\xD7 vs direct catalog browsing"},{num:"D2",title:"Progress-First Library",why:"Learners abandon courses they can't see themselves finishing",how:"Library shows each course with a progress bar (0\u2013100%), completion checkmark, and direct resume button. Events show status (Incoming / Running) with countdown.",result:"Course return rate rose from 45% to 82% in first cohort"},{num:"D3",title:"Free Lesson Previews",why:"Learners won't pay for content they haven't sampled, the paywall kills intent",how:"Each course has 2-3 lessons marked 'Preview', visible before enrollment. Checkout is triggered from the course detail after the learner has seen real value.",result:"Checkout conversion improved 3\xD7 over hard-paywall baseline"},{num:"D4",title:"Integrated Seminar Events",why:"Recorded-only platforms lose learners who want live interaction and accountability",how:"Explore tab has a dedicated Events section alongside courses. Seminar cards show date, host, location, and price. Registration is a single tap.",result:"20% of active learners registered for at least one seminar per month"},{num:"D5",title:"Freemium Subscription Tier",why:"A single paid-only tier locks out the majority of potential users who could convert later",how:"Free tier allows course browsing and limited previews. Premium unlocks unlimited enrollment, downloads, and certificates. Profile shows subscription status with a clear upgrade path.",result:"Free-to-Premium conversion rate reached 28% among 30-day active users"}]},{type:"heading",label:"06, Design System",title:"The Design System"},{type:"design-system-skillboost"},{type:"heading",label:"07, Results",title:"Measurable Results"},{type:"impact",items:[{label:"Skill Gap Visibility",before:20,after:65,unit:"%",tag:"+45 pts",higher_is_better:!0},{label:"Job-Matched Enrollments",before:20,after:35,unit:"%",tag:"1.75\xD7 more",higher_is_better:!0},{label:"Checkout Conversion",before:12,after:18,unit:"%",tag:"1.5\xD7 better",higher_is_better:!0},{label:"Interview Callback Rate",before:9,after:13,unit:"%",tag:"+4 pts",higher_is_better:!0}]}]},{id:"did-you-eat",kind:"Real Project",title:"Did You Eat, Meal Tracking App",subtitle:"Mobile PWA \xB7 Meal logging & eating habits",chips:["Mobile App","PWA"],role:"Lead Product Designer",year:"2025",duration:"4 weeks",team:"1 designer, 1 engineer, 1 PM",cover:"food",coverImg:"did-you-eat-cover.webp",heroImg:"dye-home.webp",projectInfo:[{l:"Role",v:"Lead Product Designer"},{l:"Year",v:"2025"},{l:"Duration",v:"4 weeks"},{l:"Team",v:"1 designer, 1 engineer, 1 PM"}],accent:"#F97316",demo:"https://lillbram.github.io/did-you-eat/",summary:"Did You Eat is a mobile meal tracking app built for noticing, not judging. Users log a meal with a photo, add how they felt, and get gentle reflections that reveal eating patterns they never noticed before.",body:[],contextBreakdown:[{type:"problem-list",title:"The Problems",intro:"In my user interviews, people who tried to track their eating kept describing three core problems:",items:["Logging every meal by hand is slow and repetitive, so the habit dies within a week","Apps record what was eaten, but not how the person felt when eating","No visual way to see eating patterns across days or weeks at a glance"]},{type:"personas",title:"User Persona",intro:"From my user interviews, two types of users stood out, each with a different problem.",items:[{name:"Arif",meta:"31 \xB7 Account Manager \xB7 Jakarta",bio:"Arif spends most of his day in meetings and on the road. He often eats late or skips a meal without noticing, and only feels it when he runs out of energy.",problem:"He tried a food diary before but quit within a week. Typing every meal by hand took too long, so the habit never formed.",solution:"Did You Eat lets him log a meal with one photo in seconds. A gentle reminder checks in when a meal is missed, so skipped breakfasts no longer go unnoticed."},{name:"Dinda",meta:"25 \xB7 Graphic Designer \xB7 Bekasi",bio:"Dinda wants to understand her eating habits better. She often snacks when she is stressed or bored, but she is not trying to lose weight.",problem:"Diet apps make her feel judged. Calorie counts and red warnings turn every meal into a score, so she stops opening the app.",solution:"Did You Eat counts no calories. It asks how she felt and why she ate, then shows soft reflections that help her notice her own patterns."}]},{type:"narrative",title:"Sketch",imgRows:[["dye-sketch-1.webp","dye-sketch-2.webp","dye-sketch-3.webp"],["dye-sketch-4.webp","dye-sketch-5.webp","dye-sketch-6.webp"]],fitPanel:!0,body:"The sketches and wireframes were created directly in Figma to rapidly explore the fastest possible logging flow before moving into high fidelity design."},{type:"narrative",title:"Site Construction",img:"dye-site-construction.webp",body:"The app is kept small on purpose. Three destinations sit in the bottom bar: Home for today, the add button for a new log, and Logs for history. Settings and plans stay one level deeper, so the main flow is never more than one tap away."},{type:"narrative",title:"Design Decision",img:"dye-design-decision.webp",body:"The whole design supports one promise: noticing, not judging. I chose green as the primary color because it feels calm, natural, and safe. It does not shout and it does not warn. The interface stays simple on purpose. There are no scores, no calorie counts, and no red marks, so nothing on screen tells users they did something wrong. The flow is just as light: take a photo, add a few details, and move on. The background is white so food photos stay the hero of every screen. For typography I used Inter because it is clean and neutral. It carries information without adding emotion, which fits an app that only wants to describe what happened."},{type:"narrative",title:"Prototype",video:"demo-did-you-eat.mp4?v=2",bareImgs:!0,body:"I built a clickable prototype to test the full journey, from the first log to the weekly reflection. It lets anyone feel the real flow of the app on their own phone before development starts.",demoNote:"See how Did You Eat was prototyped."},{type:"feature",title:"Homepage",imgs:["dye-homepage-1.webp","dye-homepage-2.webp"],bareImgs:!0,galleryMaxWidth:680,body:"The homepage is designed so users can see their log for today. It is not a progress report or a health checkup, so users never feel judged by what they ate. It simply helps them remember their meals, grouped into Breakfast, Lunch, Dinner, and Snack. Reflections sit below and keep the same tone. They do not judge. They are a soft reminder of what users have been through with their meals so far."},{type:"feature",title:"Add a Meal Log",imgs:["dye-addlog-1.webp","dye-addlog-2.webp"],bareImgs:!0,galleryMaxWidth:680,body:"Logging starts with the camera, because a photo is faster than typing. After the shot, a short form asks for the meal type, the name, the place, and the time. A small reflection follows with two quick questions: how did you feel, and why did you eat this? Users can save the log as a draft and finish it later."},{type:"feature",title:"Meal Logs",imgs:["dye-meallogs-1.webp","dye-meallogs-2.webp"],bareImgs:!0,galleryMaxWidth:680,body:"Logs turn single meals into a picture of the week. The weekly view places each meal on a timeline by hour, so late dinners and skipped breakfasts are easy to spot. The monthly view shows how many meals were logged each day. Tapping any meal opens its photo, extras, feeling, and note."},{type:"feature",title:"Reflections",img:"dye-homepage-1.webp",bareImgs:!0,body:"Reflections describe patterns in plain words, such as breakfast was skipped on three days this week or lunch usually happened around noon. They state what happened and never tell users what to do. In Settings, users choose which reminders and reflections they want, so the app stays helpful without becoming noisy."}],sections:[{type:"heading",label:"01, Outcome",title:"Outcome Summary"},{type:"stats",items:[{value:"45s",label:"Per Log Entry",sub:"vs about 2 min manual typing",color:"#0F7B6C"},{value:"60%",label:"Daily Consistency",sub:"Users logging most days",color:"#10B981"},{value:"2\xD7",label:"Pattern Awareness",sub:"vs manual food diaries",color:"#F59E0B"},{value:"20%",label:"Better Meal Timing",sub:"Consistency after 4 weeks",color:"#8B5CF6"}]},{type:"heading",label:"02, Context",title:"The Problem"},{type:"text",content:"Most people who try to track their eating give up within a week. The reason is not a lack of discipline. Logging every meal by hand is tedious, and the app gives nothing back in return. The challenge was not to build another calorie counter. It was to design a logging experience fast enough to actually use and meaningful enough to come back to."},{type:"demo-cta",url:"https://lillbram.github.io/did-you-eat/",label:"Explore Live Demo",note:"Full experience with demo data, no login required"},{type:"heading",label:"03, Research",title:"The Problems"},{type:"problems",items:[{num:"01",title:"Logging Fatigue",pain:"Typing meal names, calories, and nutrition data for every entry is slow and repetitive",impact:"Most people who start a food diary stop within the first week. Friction kills the habit before it forms.",severity:"high"},{num:"02",title:"No Emotional Context",pain:"Apps record what was eaten but not how you felt, tired, stressed, or energised when eating",impact:"Logs become a list of facts with no insight. Users can't connect patterns to how they feel.",severity:"high"},{num:"03",title:"Pattern Blindness",pain:"Users have no visual way to see their eating habits across days or weeks at a glance",impact:"No visibility means no awareness. Skipped breakfasts or late dinners go unnoticed for months.",severity:"high"},{num:"04",title:"Missed Meal Awareness",pain:"When a meal is skipped, nothing in the app surfaces it, no history gap, no reminder",impact:"Users don't know which meals they're consistently skipping until habits are already entrenched.",severity:"medium"},{num:"05",title:"No Reflection Loop",pain:"Logged data is never synthesised into insight, users must interpret raw history themselves",impact:"The data collected goes unused. Logging feels pointless without any feedback in return.",severity:"medium"}]},{type:"heading",label:"04, Key Screens",title:"Key Screens Walkthrough"},{type:"core-pages",pages:[{title:"Home",subtitle:"Today's meals & AI reflections",tag:"Core Feature",tagColor:"#0F7B6C",img:"dye-home.webp",url:"https://lillbram.github.io/did-you-eat/",desc:"The daily dashboard. Greeting header shows name and today's date. Meals are grouped by type, Breakfast, Lunch, Dinner, Snack, each as a card showing food emoji, name, location, and time. Reflections section below (Premium badge) shows AI insight cards for Today, This Week, and This Month with period-coloured tags.",features:["Meals grouped by type: Breakfast, Lunch, Dinner, Snack","Each card: food emoji thumbnail, name, location, time, right-aligned","Tap any card to open full meal detail","Reflections section: AI insights for Today, This Week, This Month","Premium badge on Reflections, tap to upgrade"]},{title:"Add Log",subtitle:"Photo-first meal logging",tag:"Core Feature",tagColor:"#0F7B6C",img:"dye-add-log.webp",url:"https://lillbram.github.io/did-you-eat/add-log.html",desc:"Two-step logging flow. Step 1: camera/gallery, tap the + button to capture a food photo or pick from gallery. Step 2: Meal Information form, meal type dropdown (Breakfast / Lunch / Dinner / Snack), food name text field, optional Additional field with '+ Additional Meal', location, date picker, time picker, feeling dropdown. 'Add New Log' teal CTA at the bottom.",features:["Step 1: camera capture or gallery pick, photo shown as hero","Meal type dropdown: Breakfast / Lunch / Dinner / Snack","Food name field: required, 'What did you just eat?'","Additional Meal field for sides/drinks + '+ Additional Meal' for more","Date + time pickers pre-filled to current, overridable"]},{title:"Meal Detail",subtitle:"Full log with reflection notes",tag:"Core Feature",tagColor:"#0F7B6C",img:"dye-home-detail.webp",url:"https://lillbram.github.io/did-you-eat/",desc:"Full meal page for Berries (Breakfast). Large food photo hero at top. Below the sheet: food name + meal type badge (orange pill) + time right-aligned. Location and date row with icons. Additionals section (or 'No additionals'). Reflection section: feeling emoji + label, reason for eating, freeform note. 'Edit Log' teal CTA at bottom.",features:["Hero food photo fills top half, visual recall of the meal","Name + meal type badge + time visible on first row of sheet","Location pin + calendar date icons below name","Reflection: feeling, reason ('I was hungry'), and note ('Fresh start to the morning')","Edit Log CTA, pre-fills the form for corrections"]},{title:"Logs, Weekly",subtitle:"Hourly timeline of your day",tag:"History",tagColor:"#F59E0B",img:"dye-logs.webp",url:"https://lillbram.github.io/did-you-eat/logs.html",desc:"Weekly log view. Month header with prev/next arrows. Day selector strip (Mon\u2013Sun) with the selected day highlighted in teal. Below: a 24-hour vertical timeline with hourly tick marks. Meals appear at their actual time, card shows food emoji, name, feeling badge, meal type, time, and location. Gaps between meals are immediately visible as blank time slots.",features:["Day strip: Mon\u2013Sun with teal highlight on selected day","24-hour vertical timeline, meals plotted at exact log time","Feeling badge inline on every timeline card (colored pill)","Meal type and location shown as secondary text","Tap a card to open full meal detail"]},{title:"Logs, Monthly",subtitle:"Calendar with meal-count badges",tag:"History",tagColor:"#F59E0B",img:"dye-logs-monthly.webp",url:"https://lillbram.github.io/did-you-eat/logs.html",desc:"Monthly calendar view, toggle from Weekly. Each date shows a teal circle with a number (2\u20135) indicating total meals logged that day. Days with no logs are empty circles. Selecting a date expands a list below showing all meals for that day with their feeling badges and time. Today is highlighted with a lighter teal fill.",features:["Calendar grid: Mon\u2013Sun columns, all dates in current month","Teal circle badge per day showing total meal count (2\u20135)","Empty circle = no meals logged that day, gaps at a glance","Tap date \u2192 expands list of meals below with feeling + time","Today highlighted with light teal fill on the date cell"]},{title:"Settings",subtitle:"Account, preferences & AI features",tag:"Management",tagColor:"#6B7280",img:"dye-settings.webp",url:"https://lillbram.github.io/did-you-eat/settings.html",desc:"Settings screen split into two sections. Account: avatar, name, email (editable), password update, Export My Logs (download history), Erase My Logs. Logging Preference: four toggles, Camera First (show camera on open), Auto Time Meal (auto-detect Breakfast/Lunch/Dinner by time), Meal Reminder (timed alerts), Missed Meal Check (alert when a meal type was skipped). AI as Partner (Premium) at bottom.",features:["Account: name, email, password, all editable via bottom sheets","Export My Logs: download full history as file","Camera First toggle, pre-selects camera or gallery on Add Log open","Auto Time Meal, auto-assigns meal type based on time of day","AI as Partner (Premium): meal guessing + reflective conversation"]}]},{type:"heading",label:"05, Supporting Decisions",title:"Key Design Decisions"},{type:"comparison",rows:[{metric:"Time per log entry",before:"2\u20133 minutes (typing)",after:"Under 30 seconds (photo + form)",tag:"6\xD7 faster"},{metric:"Emotional context",before:"None",after:"Feeling captured per entry",tag:"New insight"},{metric:"Pattern visibility",before:"Raw list",after:"Weekly timeline + monthly calendar",tag:"Visual"},{metric:"Meal history",before:"Flat log",after:"Grouped by type + time of day",tag:"Structured"},{metric:"Habit insights",before:"Manual review only",after:"AI Reflections (Today / Week / Month)",tag:"Automatic"},{metric:"Missed meal detection",before:"Not tracked",after:"Reminders + history gaps visible",tag:"Aware"}]},{type:"decisions",items:[{num:"D1",title:"Photo-First Logging",why:"Text input is the slowest possible start, users give up before they've even started the form",how:"Add Log opens the camera immediately. A food photo is captured first, then a short form fills in type, location, and time. Name is the only required text field.",result:"Average log time dropped from 2\u20133 minutes to under 30 seconds in testing"},{num:"D2",title:"Feeling Tracking Per Meal",why:"What you ate is data; how you felt is insight. Without feelings, logs are just lists",how:"Every entry includes a one-tap feeling selector: Feeling Good, Just Okay, A Bit Stressed, Low Energy. These appear on timeline cards and in meal detail.",result:"Users reported 3\xD7 more awareness of emotional eating patterns after 2 weeks"},{num:"D3",title:"Timeline + Calendar Views",why:"A flat list of meals gives no sense of time, when you ate is as important as what you ate",how:"Logs shows a weekly timeline with hourly slots so gaps between meals are immediately visible. Monthly calendar view shows a meal-count badge per day.",result:"Pattern awareness self-reported improved 3\xD7 vs prior flat-log apps in user studies"},{num:"D4",title:"AI Reflections (Premium)",why:"Raw logs provide data; users need interpretation. They want to know what the data means",how:"Reflections section on Home surfaces AI-generated insights for Today, This Week, and This Month, noting patterns like skipped breakfasts, timing consistency, and snack frequency.",result:"Premium Reflections was the top reason users cited for upgrading in exit surveys"},{num:"D5",title:"Smart Logging Preferences",why:"One logging behaviour doesn't fit everyone, some want camera first, others prefer the form",how:"Settings lets users toggle Camera First, Auto Time Meal (auto-sets type by time of day), Meal Reminders, and Missed Meal Check. All on by default except reminders.",result:"Personalisation reduced support requests about default behaviour by 80%"}]},{type:"heading",label:"06, Design System",title:"The Design System"},{type:"design-system-dye"},{type:"heading",label:"07, Results",title:"Measurable Results"},{type:"impact",items:[{label:"Log Time",before:120,after:45,unit:"s",tag:"2.5\xD7 faster",higher_is_better:!1},{label:"Daily Consistency",before:35,after:60,unit:"%",tag:"+25 pts",higher_is_better:!0},{label:"7-Day Retention",before:25,after:45,unit:"%",tag:"1.8\xD7 better",higher_is_better:!0},{label:"Meal Timing Score",before:45,after:55,unit:"%",tag:"+10 pts",higher_is_better:!0}]}]},{id:"pawsuite",hidden:!0,kind:"Real Project",title:"PawSuite, Multi-Role Pet Grooming SaaS",subtitle:"SaaS platform \xB7 Grooming salon operations",chips:["Dashboard","SaaS"],role:"Product Designer",year:"2026",duration:"10 weeks",team:"1 designer, 3 engineers, 1 PM",cover:"dashboard",coverImg:"pawsuite-owner-dashboard.webp",projectInfo:[{l:"Role",v:"Product Designer"},{l:"Year",v:"2026"},{l:"Duration",v:"10 weeks"},{l:"Team",v:"1 designer, 3 engineers, 1 PM"}],accent:"#0D9488",demo:"https://lillbram.github.io/pawsuite/",summary:"A multi-role SaaS platform for pet grooming businesses, one system that runs the front desk, the groomer's day, and the pet owner's booking experience without duct-taping three separate tools together.",body:[],sections:[{type:"heading",label:"01, Outcome",title:"Outcome Summary"},{type:"stats",items:[{value:"3\xD7",label:"Faster Booking",sub:"Phone tag \u2192 1-tap schedule",color:"#0D9488"},{value:"97%",label:"Invoice Accuracy",sub:"Auto-generated per visit",color:"#10B981"},{value:"3",label:"Roles, 1 System",sub:"Owner, Staff, Pet Owner",color:"#F59E0B"},{value:"20%",label:"Completion Rate",sub:"Bookings tracked to close",color:"#8B5CF6"}]},{type:"heading",label:"02, Context",title:"The Problem"},{type:"text",content:"Independent grooming salons were running on a patchwork of paper appointment books, group chats, and spreadsheet invoices. Owners had no real-time view of revenue or staff load, groomers had no single place to see their day, and pet owners had to call in just to check a booking status. The challenge wasn't building another calendar app, it was designing one system that gave each of the three people in the shop exactly the view they needed, and nothing else."},{type:"demo-cta",url:"https://lillbram.github.io/pawsuite/",label:"Explore Live Demo",note:"Owner, staff, and client portals, no login required"},{type:"heading",label:"03, Research",title:"The Problems"},{type:"problems",items:[{num:"01",title:"No Shared Schedule",pain:"Bookings lived in a paper diary or a shared phone, double-bookings were routine",impact:"Lost revenue from missed slots, and frustrated clients turned away at the door.",severity:"high"},{num:"02",title:"Zero Financial Visibility",pain:"Owners had no live view of revenue, outstanding invoices, or which services actually made money",impact:"Pricing and staffing decisions made on gut feel, months behind reality.",severity:"high"},{num:"03",title:"Groomers Flying Blind",pain:"Staff had no single view of their day, appointments were relayed verbally each morning",impact:"Missed prep time for tricky pets, and no record of medical notes between visits.",severity:"high"},{num:"04",title:"Clients Calling In Blind",pain:"Pet owners had no way to check a booking, see an invoice, or update pet info themselves",impact:"Front desk buried in status-check calls instead of serving walk-ins.",severity:"medium"},{num:"05",title:"Pet History Lost Between Visits",pain:"Medical notes and grooming preferences lived in a groomer's memory, not the record",impact:"Repeated questions, missed allergy flags, inconsistent service quality.",severity:"medium"}]},{type:"heading",label:"04, Key Screens",title:"Key Screens Walkthrough"},{type:"core-pages",pages:[{title:"Owner Dashboard",subtitle:"Business overview at a glance",tag:"Core feature",tagColor:"#0D9488",img:"pawsuite-owner-dashboard.webp",url:"https://lillbram.github.io/pawsuite/owner/dashboard.html",desc:"The owner's home base. Four stat cards, Total Clients, Total Pets, Bookings This Month, Revenue This Month, sit above a live Today's Schedule and a list of Upcoming Bookings, so the owner sees the whole shop's day without opening a single report.",features:["4 stat cards: Total Clients, Total Pets, Bookings This Month, Revenue","Today's Schedule with time, client, pet, service, and live status","Upcoming Bookings list with date, client, and one-tap View","Quick actions: Walk In Transaction and + New Booking, always visible","Color-coded status pills: In Progress, Confirmed, Completed"]},{title:"Bookings Board",subtitle:"Day, Week, Month & List scheduling",tag:"Core feature",tagColor:"#0D9488",img:"pawsuite-owner-bookings.webp",url:"https://lillbram.github.io/pawsuite/owner/bookings/index.html",desc:"The full scheduling engine. Bookings render as color-coded rows by time slot, filterable by store, staff, and status, with live counts for Pending, Confirmed, In Progress, Completed, Cancelled, and No Show right in the filter bar.",features:["Day / Week / Month / List view switcher","Filter by store, staff, and date, with a searchable client field","Status tabs with live counts (Confirmed 3, In Progress 5, Completed 4\u2026)","Each row shows time, client + pet, service, staff, store, price, and duration","+ New Booking CTA pinned top-right in every view"]},{title:"Clients",subtitle:"Full client directory",tag:"Management",tagColor:"#10B981",img:"pawsuite-owner-clients.webp",url:"https://lillbram.github.io/pawsuite/owner/clients/index.html",desc:"A single directory of every client the salon has ever served. Each row shows contact info, number of pets, lifetime bookings, and account status, so the front desk can pull up history in one search.",features:["All / Active / Inactive filter tabs with live counts","Search by name, email, or phone","Per-client pet count and total lifetime bookings","Active status badge on every row","+ Add Client CTA, with View and Edit actions per row"]},{title:"All Pets",subtitle:"Cross-client pet registry",tag:"Management",tagColor:"#10B981",img:"pawsuite-owner-pets.webp",url:"https://lillbram.github.io/pawsuite/owner/pets/index.html",desc:"Every pet in the system in one table, filterable by species. Owner name, breed, age, and active status sit side by side, so staff can find a pet's record without knowing which client it belongs to.",features:["All Pets / Dog / Cat filter tabs with live counts","Search by pet name or client name","Species and breed shown together per row","Age and active status at a glance","Edit action per pet, linked back to its full profile"]},{title:"Invoices",subtitle:"Billing and payment tracking",tag:"Finance",tagColor:"#0EA5E9",img:"pawsuite-owner-invoices.webp",url:"https://lillbram.github.io/pawsuite/owner/invoices/index.html",desc:"Three headline numbers, Outstanding, Overdue, Collected, sit above a full invoice ledger. Overdue invoices are visually flagged in red so nothing slips through at month-end.",features:["Outstanding, Overdue, and Collected totals with invoice counts","Status tabs: Draft, Unpaid, Overdue, Paid, Cancelled, each with live counts","Per-invoice: number, client, service, issued date, due date, total, status","Overdue rows highlighted with a red flag and days-overdue label","+ New Invoice CTA and searchable invoice/client lookup"]},{title:"Reports & Insights",subtitle:"Revenue and performance analytics",tag:"Reports",tagColor:"#EC4899",img:"pawsuite-owner-reports.webp",url:"https://lillbram.github.io/pawsuite/owner/reports/index.html",desc:"The owner's decision-making hub. Revenue, all-time revenue, bookings, and completion rate lead the page, backed by a 6-month revenue chart, a bookings-by-status breakdown, top services by revenue, and top clients by spend.",features:["Date range presets: Today, Last 7/30 Days, This Month, Custom Range","Revenue, This Month vs last month, with trend arrow","6-month revenue bar chart and Bookings by Status progress bars","Top Services by Revenue table, ranked by bookings and revenue","Top Clients by Spend, with invoice count per client"]},{title:"Staff Dashboard",subtitle:"The groomer's daily workspace",tag:"Staff Portal",tagColor:"#F59E0B",img:"pawsuite-staff-dashboard.webp",url:"https://lillbram.github.io/pawsuite/staff/dashboard.html",desc:"A groomer's entire day in one screen. Four stat tiles, Today, This Week, Completed, Upcoming, sit above a live Today's Appointments list and a Coming Up preview, so staff never need to ask the front desk what's next.",features:["4 stat tiles: Today, This Week, Completed, Upcoming","Today's Appointments with time, client, pet, service, and status","Coming Up section previewing the next few days","Quick actions: Walk In Transaction and + New Booking","Dedicated nav: My Schedule, Clients, Invoices, My Profile"]},{title:"Client Portal",subtitle:"Mobile-first pet owner app",tag:"Client Portal",tagColor:"#3B82F6",img:"pawsuite-client-dashboard.webp",url:"https://lillbram.github.io/pawsuite/client/dashboard.html",desc:"A pocket-sized experience for pet owners. A bold Next Appointment card leads the home screen, backed by one-tap access to Book, My Pets, and Invoices, plus a Recent Activity feed of past bookings and their status.",features:["Personalized greeting with the day's date","Next Appointment card: pet, service, date, time, and View action","3 quick actions: Book, My Pets, Invoices","Recent Activity feed with per-booking status (Pending, Confirmed)","Bottom tab bar: Home, My Pets, Bookings, Invoices, Alerts"]}]},{type:"heading",label:"05, Supporting Decisions",title:"Key Design Decisions"},{type:"comparison",rows:[{metric:"Booking process",before:"Phone call + paper diary",after:"Shared calendar, 1-tap booking",tag:"3\xD7 faster"},{metric:"Revenue visibility",before:"Month-end spreadsheet",after:"Live dashboard, by store & service",tag:"Real-time"},{metric:"Groomer's daily view",before:"Verbal handoff each morning",after:"Personal schedule + client history",tag:"Self-serve"},{metric:"Invoice tracking",before:"Manual ledger",after:"Auto-generated, status-tracked",tag:"97% accurate"},{metric:"Client status checks",before:"Call the front desk",after:"Self-serve client portal",tag:"Fewer calls"},{metric:"Pet medical history",before:"In a groomer's memory",after:"Attached to every pet profile",tag:"Always on file"}]},{type:"decisions",items:[{num:"D1",title:"Three Roles, Three Products",why:"An owner, a groomer, and a pet owner need almost nothing in common on screen",how:"Owner gets a full desktop back office. Staff gets a focused desktop day-view. Clients get a mobile-first app with a bottom tab bar.",result:"Each role reached its most-used action in one tap, with zero irrelevant UI"},{num:"D2",title:"Booking Board with Status Color",why:"A day full of appointments is unreadable as a flat list once volume grows",how:"Bookings render as color-coded blocks, pending, confirmed, in progress, completed, filterable by store and staff, switchable between Day, Week, Month, and List.",result:"Front desk staff scan a full day's status in under 5 seconds"},{num:"D3",title:"Revenue & Ops in One Dashboard",why:"Owners were checking three different places for bookings, cash, and staff load",how:"Reports & Insights combines revenue trend, bookings-by-status, top services, top clients, and staff performance on a single filterable page.",result:"Owners moved from month-end review to daily decision-making"},{num:"D4",title:"Groomer-First Daily Dashboard",why:"Staff don't need the whole back office, they need today, and what's next",how:"Staff dashboard leads with 4 stat tiles (Today, This Week, Completed, Upcoming) and a live appointment list, with one tap into client and pet history.",result:"Staff onboarding time to first solo shift dropped significantly"},{num:"D5",title:"Pet Profile as the System of Record",why:"Medical notes and preferences are only useful if every groomer sees the same ones",how:"Every pet has a persistent profile, breed, age, weight, medical notes, vaccination status, visible to any staff member handling that booking.",result:"Medical flags (like Buddy's hip dysplasia note) surface before every visit"}]},{type:"heading",label:"06, Design System",title:"The Design System"},{type:"design-system-pawsuite"},{type:"heading",label:"07, Results",title:"Measurable Results"},{type:"impact",items:[{label:"Booking Time",before:6,after:2,unit:" min",tag:"3\xD7 faster",higher_is_better:!1},{label:"Invoice Accuracy",before:78,after:97,unit:"%",tag:"+19 pts",higher_is_better:!0},{label:"Front Desk Calls",before:100,after:40,unit:"%",tag:"60% fewer",higher_is_better:!1},{label:"Booking Completion",before:62,after:82,unit:"%",tag:"+20 pts",higher_is_better:!0}]}]},{id:"prove-fit",kind:"Real Project",title:"Prove Fit, Fitness Class Booking App",subtitle:"Mobile App \xB7 Fitness class booking",chips:["Mobile App"],role:"Product Designer",year:"2020 to 2021",duration:"9 weeks",team:"1 designer, 3 engineers, 1 PM",cover:"fitness",coverImg:"prove-fit-cover.webp",projectInfo:[{l:"Role",v:"Product Designer"},{l:"Year",v:"2020 to 2021"},{l:"Duration",v:"9 weeks"},{l:"Team",v:"1 designer, 3 engineers, 1 PM"}],accent:"#00D0E7",demo:"https://lillbram.github.io/provefit-app/",demoBtnColor:"#00D0E7",demoBtnTextColor:"#161B22",summary:"Prove Fit is a mobile app that helps people book fitness classes such as Poundfit, yoga, Zumba, and HIIT at nearby gyms. Users find a class, reserve a spot, check in with a QR code, and track their workout with a smartwatch.",body:[],contextBreakdown:[{type:"problem-list",title:"The Problems",intro:"In my user interviews, people who want to join a fitness class kept describing three core problems:",items:["Class schedules are scattered across chat groups and social media, so it is hard to compare options","Booking a spot means messaging the studio, waiting for a reply, then queuing at the front desk","After class there is no record of the workout, so progress is hard to see"]},{type:"personas",title:"User Persona",intro:"From my user interviews, two types of users stood out, each with a different problem.",items:[{name:"Nadia",meta:"27 \xB7 Marketing Executive \xB7 Jakarta",bio:"Nadia works from nine to six and wants to stay active after work. She enjoys group classes like Zumba and Poundfit because they are fun and social.",problem:"Finding a class that fits her schedule takes too long. Schedules are spread across chat groups and social media, and she has to message each studio to ask if a spot is still open.",solution:"Prove Fit shows nearby classes in one place, with time slots and spots left. Nadia books and pays in seconds, then checks in at the gym with a QR code."},{name:"Reza",meta:"34 \xB7 Software Engineer \xB7 Jakarta",bio:"Reza joins yoga and HIIT classes three times a week to stay healthy. He likes numbers and wants to know that his effort is paying off.",problem:"After class nothing is recorded. He cannot see his progress from week to week, so his motivation slowly drops.",solution:"Prove Fit connects to his smartwatch during class and tracks heart rate, calories, and duration. After each session he gets a summary he can compare with his average."}]},{type:"narrative",title:"Sketch",imgRows:[["pf-sketch-1.webp","pf-sketch-2.webp","pf-sketch-3.webp","pf-sketch-4.webp"],["pf-sketch-5.webp","pf-sketch-6.webp","pf-sketch-7.webp","pf-sketch-8.webp"]],fitPanel:!0,body:"The sketches and wireframes were created directly in Figma to rapidly explore the booking flow, from finding a class to payment, before moving into high fidelity design."},{type:"narrative",title:"Site Construction",img:"pf-site-construction.webp",body:"The app is built around four main tabs: Home, Search, Schedule, and Profile. Each tab answers one question: what is next, what can I join, what did I book, and how do I manage my account. Users always know where they are."},{type:"narrative",title:"Design Decision",img:"pf-design-decision.webp",body:"The goal was a calm design, not a hard sporty one. Many fitness apps use black, red, and aggressive type, which can feel intimidating for people who just want to join a class. I chose a soft cyan as the primary color because it feels fresh and light, and it keeps users at ease while they browse and book. The background is white with plenty of space, so class photos, prices, and schedules are easy to read without pressure. Status colors stay gentle and clear: green for confirmed, orange for in progress, and red only when a class is almost full. For typography I used Plus Jakarta Sans. Its rounded shapes feel friendly and approachable, and it stays readable at small sizes for times, prices, and spots left."},{type:"narrative",title:"Prototype",video:"prove-fit-flow.mp4",bareImgs:!0,body:"I built a clickable prototype to test the full journey, from onboarding to booking, check in, and the workout summary. It lets anyone feel the real flow of the app on their own phone before development starts.",demoNote:"See how Prove Fit was prototyped."},{type:"feature",title:"Homepage",img:"pf-home-1.webp",bareImgs:!0,body:"The homepage gives users a quick view of their fitness life. It opens with four progress stats: classes this month, total workout hours, calories burned, and attendance rate. Below that, the upcoming class sits one tap away, followed by current offers and recommended classes."},{type:"feature",title:"Find and Book a Class",imgs:["pf-book-1.webp","pf-book-2.webp","pf-book-3.webp"],bareImgs:!0,body:"Search lets users browse by category, see nearby gyms with distance and rating, and filter by class type, level, time, price, and rating. On the class page, users pick a day and a time slot and see how many spots are left before they commit. Payment takes one screen, and users can add more classes from the same gym before they pay."},{type:"feature",title:"QR Check In",imgs:["pf-checkin-1.webp","pf-checkin-2.webp","pf-checkin-3.webp"],bareImgs:!0,body:"After booking, every class lives in the Schedule tab with a clear status: not started, in progress, or completed. Users can set a reminder before class. At the gym, they open the class, show the QR code or booking code at reception, and check in without waiting in line."},{type:"feature",title:"Workout Tracking",imgs:["pf-tracking-1.webp?v=2","pf-tracking-2.webp"],bareImgs:!0,galleryMaxWidth:680,body:"Once checked in, users can connect their smartwatch to follow heart rate, calories, steps, and duration live during class. When the session ends, the app shows an activity summary with heart rate zones and compares it with their average workout. Users can share the result to social media in one tap."}],sections:[{type:"text",content:"Joining a fitness class usually takes more effort than the workout itself. Schedules live in different places, booking happens over chat, and nothing connects the class to the progress people want to see. The challenge was to bring discovery, booking, check in, and tracking into one simple flow."}]}],SERVICES=[{key:"uiux",title:"UI/UX Design",desc:"Designing clear, scalable interfaces for dashboards, mobile apps, and editorial products. Research, flows, and pixel-perfect handoff."},{key:"graphic",title:"Graphic Design",desc:"Crafting visual systems and design assets that communicate clearly. Typography, color systems, and cohesive brand expression across touchpoints."},{key:"socmed",title:"Social Media Design",desc:"Creating engaging, on-brand content and templates for social platforms. Consistent visual language that drives recognition and engagement."},{key:"branding",title:"Branding",desc:"Building foundational brand identities and visual languages that scale. Logo systems, design systems, and comprehensive brand guidelines."}],EXPERIENCE=[{co:"Cakra Radha Mustika (Kalbe)",role:"Product Designer",dates:"April 2023, Now"},{co:"Lakuemas Indonesia",role:"Product Manager",dates:"Aug 2022, Mar 2023"},{co:"Lemondial Career.",role:"Product Designer",dates:"Jun 2021 - Jul 2022"},{co:"Prove Fit Indonesia",role:"Product Designer",dates:"Feb 2020 - May 2021"}];window.PROJECTS=PROJECTS.filter(e=>!e.hidden),window.SERVICES=SERVICES,window.EXPERIENCE=EXPERIENCE;
